package com.atlasiq.twin;
import com.atlasiq.intelligence.*;import com.atlasiq.persistence.*;import jakarta.enterprise.context.ApplicationScoped;import java.time.*;import java.util.*;
@ApplicationScoped public class ArchitectureBlackBoxService {private final AnalysisStore store;private final ArchitectureDiffService diffs;public ArchitectureBlackBoxService(AnalysisStore s,ArchitectureDiffService d){store=s;diffs=d;}public Timeline timeline(String repository,String system,Instant before,Instant after){List<StoredAnalysis>h=store.history(repository,system,200).stream().filter(x->!x.createdAt().isBefore(before)&&!x.createdAt().isAfter(after)).sorted(Comparator.comparing(StoredAnalysis::createdAt)).toList();List<Transition>t=new ArrayList<>();for(int i=1;i<h.size();i++){var a=h.get(i-1);var b=h.get(i);t.add(new Transition(a.id(),b.id(),b.createdAt(),diffs.compare(a.id(),b.id())));}return new Timeline(before,after,List.copyOf(t));}public record Transition(String from,String to,Instant at,ArchitectureDiff diff){}public record Timeline(Instant before,Instant after,List<Transition>transitions){}}
